import {automaticScreenshotPlan} from './roster-import-model.mjs?v=2';
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
export function initScreenshotImport({catalog,getSnapshot,onSave,host=document.querySelector('.roster-cloud-actions')}){
 const open=node('button','Import screenshots','btn secondary');open.type='button';open.id='roster-screenshot-open';host.append(open);
 const dialog=node('dialog',undefined,'screenshot-import');dialog.setAttribute('aria-labelledby','screenshot-import-title');const title=node('h2','Import Tatari screenshots');title.id='screenshot-import-title';const header=node('header',undefined,'screenshot-import-head'),close=node('button','×');close.type='button';close.setAttribute('aria-label','Close screenshot import');header.append(title,close);
 const body=node('div',undefined,'screenshot-import-body'),intro=node('p','Choose screenshots to update your Tatari automatically.','screenshot-import-intro'),privacy=node('p','Images are processed on this device. Only detected settings are saved.','screenshot-import-note'),rules=node('p','Rainbow background means T4, regardless of appearance. Other unclear backgrounds keep a saved tier. Food is set to the detected letter’s minimum; adjust it later in My Tatari. Unclear cards are skipped.','screenshot-import-note');
 const upload=node('label','Choose screenshots','screenshot-import-upload'),input=node('input');input.type='file';input.accept='image/*';input.multiple=true;upload.append(input);const progress=node('p','','screenshot-import-progress');progress.setAttribute('role','status');progress.setAttribute('aria-live','polite');const error=node('p','','screenshot-import-error');error.setAttribute('role','alert');const list=node('div',undefined,'screenshot-import-list'),actions=node('footer',undefined,'screenshot-import-actions'),done=node('button','Close','btn secondary'),undoButton=node('button','Undo last import','btn secondary');done.type=undoButton.type='button';undoButton.hidden=true;actions.append(undoButton,done);body.append(intro,privacy,upload,rules,progress,error,list);dialog.append(header,body,actions);document.body.append(dialog);
 let worker=null,waiter=null,bitmaps=[],serial=0,busy=false,saving=false,undo=null;
 function stop(){worker?.terminate();worker=null;if(waiter){waiter.reject(Error('Import cancelled.'));waiter=null;}}
 function free(){for(const bitmap of bitmaps)bitmap.close();bitmaps=[];}
 function reset(forgetUndo=true){serial++;stop();free();input.value='';input.disabled=false;busy=false;saving=false;list.replaceChildren();error.textContent='';progress.textContent='';if(forgetUndo)undo=null;undoButton.hidden=!undo;close.disabled=done.disabled=undoButton.disabled=false;if(dialog.open)dialog.close();}
 function request(data,transfer=[]){return new Promise((resolve,reject)=>{waiter={resolve,reject};worker.postMessage(data,transfer)});}
 async function ready(){worker=new Worker(new URL('./roster-import-worker.mjs?v=2',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress'){progress.textContent='Reading card '+data.done+' of '+data.total+'…';return;}const p=waiter;waiter=null;if(!p)return;data.type==='error'?p.reject(Error(data.message)):p.resolve(data);};worker.onerror=()=>{const p=waiter;waiter=null;p?.reject(Error('Image reading is not supported in this browser.'));};const [manifest,atlas,starAtlas]=await Promise.all([fetch(new URL('./roster-import/templates.json?v=2',import.meta.url)).then(r=>{if(!r.ok)throw Error('Image references unavailable.');return r.json()}),fetch(new URL('./roster-import/tiles.webp?v=2',import.meta.url)).then(r=>{if(!r.ok)throw Error('Portrait references unavailable.');return r.blob()}),fetch(new URL('./roster-import/stars.webp?v=2',import.meta.url)).then(r=>{if(!r.ok)throw Error('Star references unavailable.');return r.blob()})]);await request({type:'load',templates:manifest.entries,atlas,starAtlas});}
 function renderResults(plan){list.replaceChildren();for(const result of plan.results){const item=node('article',undefined,'screenshot-import-result'),box=result.detection.box,bitmap=bitmaps[result.detection.fileIndex],crop=node('canvas');crop.width=box.w;crop.height=box.h;crop.getContext('2d').drawImage(bitmap,box.x,box.y,box.w,box.h,0,0,box.w,box.h);crop.setAttribute('role','img');crop.setAttribute('aria-label',result.name+' screenshot crop');const text=node('div');text.append(node('h3',result.name));if(result.status==='ready')text.append(node('p','T'+result.tier+' · '+result.stars+' stars · Food '+result.food+' ('+result.grade+' minimum)'),node('small','Imported · tier from '+result.tierSource));else if(result.status==='unchanged')text.append(node('p','Already matches your roster.'));else text.append(node('p','Skipped · '+result.reason));item.append(crop,text);list.append(item);}}
 open.onclick=()=>{reset(false);dialog.showModal();progress.textContent='Choose up to 6 screenshots. Readable cards save automatically.';};close.onclick=done.onclick=()=>{if(!saving)reset(false)};dialog.addEventListener('cancel',event=>{event.preventDefault();if(!saving)reset(false)});
 input.onchange=async()=>{const files=[...input.files];if(!files.length)return;const token=++serial,snapshot=getSnapshot();stop();free();list.replaceChildren();error.textContent='';busy=true;input.disabled=true;undoButton.disabled=true;let plan=null;try{if(files.length>6)throw Error('Choose up to 6 screenshots.');progress.textContent='Loading image references…';await ready();if(token!==serial)return;const detections=[],failures=[];for(let i=0;i<files.length;i++){try{if(files[i].size>12*1024*1024)throw Error('Image is larger than 12 MB.');let bitmap=await createImageBitmap(files[i]);if(bitmap.width*bitmap.height>24000000){bitmap.close();throw Error('Image is too large.');}const scale=Math.min(1,900/bitmap.width,3000/bitmap.height);if(scale<1){const small=await createImageBitmap(bitmap,{resizeWidth:Math.round(bitmap.width*scale),resizeHeight:Math.round(bitmap.height*scale)});bitmap.close();bitmap=small;}const fileIndex=bitmaps.push(bitmap)-1,copy=await createImageBitmap(bitmap),result=await request({type:'scan',image:copy},[copy]);if(token!==serial)return;detections.push(...result.cards.map(card=>({...card,fileIndex})));}catch(e){if(token!==serial)return;failures.push('Screenshot '+(i+1)+': '+e.message);}}
 plan=automaticScreenshotPlan(catalog,snapshot.state,detections);if(plan.changes.length){if(!snapshot.canSave)throw Error('Log in to My Tatari to import. No settings were saved.');saving=true;close.disabled=done.disabled=true;progress.textContent='Saving '+plan.changes.length+' Tatari…';await onSave(plan,snapshot);if(token!==serial)return;undo={state:snapshot.state,snapshot:getSnapshot(),count:plan.changes.length};undoButton.hidden=false;}
 renderResults(plan);progress.textContent=plan.changes.length+' imported · '+plan.skipped+' skipped · '+plan.results.filter(r=>r.status==='unchanged').length+' unchanged.';error.textContent=failures.join(' ');if(!detections.length&&!failures.length)error.textContent='No complete cards found.';
 }catch(e){if(token===serial){progress.textContent='Import did not save.';error.textContent=e.message;if(plan){for(const result of plan.results)if(result.status==='ready'){result.status='skipped';result.reason='Not saved.';}renderResults(plan);}}}finally{if(token===serial){saving=busy=false;input.disabled=false;close.disabled=done.disabled=undoButton.disabled=false;stop();}}};
 undoButton.onclick=async()=>{if(!undo||busy)return;const previous=undo;try{saving=busy=true;close.disabled=done.disabled=undoButton.disabled=input.disabled=true;await onSave({next:previous.state,changes:Array.from({length:previous.count})},previous.snapshot);undo=null;undoButton.hidden=true;list.replaceChildren();progress.textContent='Last screenshot import undone.';}catch(e){error.textContent=e.message;}finally{saving=busy=false;close.disabled=done.disabled=undoButton.disabled=input.disabled=false;}};
 return {reset:()=>reset(true),open:()=>open.click()};
}
